from django.shortcuts import render

from .models import Produk


def daftar(request):
    produk = Produk.objects.all()
    # context: data yang bisa dipakai template
    return render(request, 'katalog/daftar.html', {
        'produk': produk,
        'judul': 'Katalog Produk',
    })

