{% extends 'katalog/base.html' %}

{% block title %}{{ judul }}{% endblock %}

{% block konten %}
  <h1>{{ judul }}</h1>
  <p>Jumlah produk: {{ produk|length }}</p>

  <table>
    <thead>
      <tr><th>Nama</th><th>Harga</th></tr>
    </thead>
    <tbody>
      {% for p in produk %}
        <tr>
          <td>{{ p.nama }}</td>
          <td>Rp {{ p.harga|floatformat:0 }}</td>
        </tr>
      {% empty %}
        <tr><td colspan="2">Belum ada produk.</td></tr>
      {% endfor %}
    </tbody>
  </table>
{% endblock %}

